/**
 * Snapshot files in a directory (non-recursive, top-level only).
 * Returns a Set of filenames.
 */
function snapshotDir(dir: string) {
  try {
    return new Set(fs.readdirSync(dir));
  } catch {
    return new Set();
  }
}

